<?php
$title='Inventario'; require __DIR__.'/partials_header.php';
$q=trim($_GET['q'] ?? '');
$sql='SELECT p.*, c.nombre AS categoria FROM productos p JOIN categorias c ON c.id_categoria=p.id_categoria WHERE 1=1'; $params=[];
if($q!==''){ $sql.=' AND (p.nombre LIKE ? OR p.codigo LIKE ? OR c.nombre LIKE ?)'; $like='%'.$q.'%'; $params=[$like,$like,$like]; }
$sql.=' ORDER BY p.estado DESC, p.nombre'; $st=db()->prepare($sql); $st->execute($params); $products=$st->fetchAll();
$total=(int)db()->query('SELECT COUNT(*) FROM productos WHERE estado=1')->fetchColumn(); $low=(int)db()->query('SELECT COUNT(*) FROM productos WHERE estado=1 AND stock_actual < stock_minimo')->fetchColumn();
?><section class="page-head"><div><p class="eyebrow">Panel de control</p><h1>Inventario de productos</h1><p class="muted">Administra existencias y movimientos de TecnoStock.</p></div><a class="btn primary" href="product_form.php">+ Nuevo producto</a></section><section class="stats"><div class="stat"><span>Productos activos</span><strong><?=$total?></strong></div><div class="stat warning"><span>Stock bajo</span><strong><?=$low?></strong></div><div class="stat"><span>Usuario</span><strong><?=e($_SESSION['user']['nombre'])?></strong></div></section><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Buscar por código, nombre o categoría"><button class="btn secondary">Buscar</button><?php if($q): ?><a class="btn ghost" href="index.php">Limpiar</a><?php endif; ?></form><div class="table-wrap"><table><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><code><?=e($p['codigo'])?></code></td><td><strong><?=e($p['nombre'])?></strong><small><?=e($p['descripcion'])?></small></td><td><?=e($p['categoria'])?></td><td>$<?=number_format((float)$p['precio'],0,',','.')?></td><td><span class="stock <?=$p['stock_actual']<$p['stock_minimo']?'low':''?>"><?=$p['stock_actual']?> / mín. <?=$p['stock_minimo']?></span></td><td><span class="badge <?=$p['estado']?'active':'inactive'?>"><?=$p['estado']?'Activo':'Inactivo'?></span></td><td class="actions"><a href="product_form.php?id=<?=$p['id_producto']?>">Editar</a><?php if($p['estado']): ?><a href="movement_form.php?id=<?=$p['id_producto']?>">Movimiento</a><form method="post" action="product_toggle.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id_producto']?>"><button data-confirm="¿Desactivar este producto?" class="link danger-text">Desactivar</button></form><?php endif; ?></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="7" class="empty">No se encontraron productos.</td></tr><?php endif; ?></tbody></table></div>
<?php require __DIR__.'/partials_footer.php';
